add_filter( 'upload_mimes', 'perfectpixel_allow_download_file_types' );
add_filter( 'wp_check_filetype_and_ext', 'perfectpixel_allow_download_file_types_check', 10, 4 );

function perfectpixel_extra_upload_types() {
	$blocked = array( 'php', 'phtml', 'phar', 'svg', 'svgz', 'html', 'htm', 'js', 'exe', 'sh', 'bat', 'cgi', 'pl', 'py', 'shtml' );
	$types   = array();
	foreach ( explode( '|', '{{extra_upload_types}}' ) as $pair ) {
		$parts = array_map( 'trim', explode( '=', $pair, 2 ) );
		$ext   = strtolower( preg_replace( '/[^a-z0-9]/i', '', $parts[0] ?? '' ) );
		if ( 2 === count( $parts ) && $ext && ! in_array( $ext, $blocked, true ) && preg_match( '#^[a-z0-9.+-]+/[a-z0-9.+-]+$#i', $parts[1] ) ) {
			$types[ $ext ] = $parts[1];
		}
	}
	return $types;
}

function perfectpixel_allow_download_file_types( $mimes ) {
	return current_user_can( 'manage_woocommerce' ) ? array_merge( $mimes, perfectpixel_extra_upload_types() ) : $mimes;
}

// Some types (e.g. epub) are detected with a generic MIME; accept the extension we explicitly allowed.
function perfectpixel_allow_download_file_types_check( $data, $file, $filename, $mimes ) {
	if ( ! empty( $data['ext'] ) || ! current_user_can( 'manage_woocommerce' ) ) {
		return $data;
	}
	$ext   = strtolower( pathinfo( $filename, PATHINFO_EXTENSION ) );
	$types = perfectpixel_extra_upload_types();
	if ( isset( $types[ $ext ] ) ) {
		$data['ext']  = $ext;
		$data['type'] = $types[ $ext ];
	}
	return $data;
}
